// Top Products API - GET /api/top-products?limit=10
interface TopProductsInput {
  limit?: number;
}

export const topProductsApi = new Api<TopProductsInput, TopProductsRow[]>(
  "top-products",
  async ({ limit = 10 }, { client, sql }) => {
    const query = sql.statement`
      SELECT product_id, view_count, cart_count, purchase_count, total_revenue
      FROM ${TopProductsView}
      ORDER BY total_revenue DESC, purchase_count DESC, view_count DESC
      LIMIT ${limit}
    `;
    const data = await client.query.execute<TopProductsRow>(query);
    return await data.json();
  }
);

